extern inline /* convert to C++ keyword */ double __attribute((gnu_inline, always_inline))
sqrt(double x)
{
 double result;





 __asm__ volatile ("vsqrt.f64 %P0, %P1" : "=w" (result) : "w" (x));




 return result;
}

extern inline /* convert to C++ keyword */ double __attribute((gnu_inline, always_inline))
fabs(double x)
{
    double result;
    __asm__ ("vabs.f64\t%P0, %P1" : "=w" (result) : "w" (x));
    return result;
}
