extern inline /* convert to C++ keyword */ double __attribute((gnu_inline, always_inline))
fma (double x, double y, double z)
{
  __asm__ volatile ("vfma.f64 %P0, %P1, %P2" : "+w" (z) : "w" (x), "w" (y));
  return z;
}







