# 1862 "/home/megabug/.arduino15/packages/arduino/hardware/zephyr/0.3.1/variants/arduino_giga_r1_stm32h747xx_m7/llext-edk/include/modules/hal/cmsis/CMSIS/Core/Include/core_cm7.h"
