typedef void (*rtio_callback_t)(struct rtio *r, const struct rtio_sqe *sqe, void *arg0);

/**
 * @brief A submission queue event
 */
struct rtio_sqe {
 uint8_t op;

 uint8_t prio;

 uint16_t flags;

 uint32_t iodev_flags;

 const struct rtio_iodev *iodev;

 /**
	 * User provided data which is returned upon operation completion. Could be a pointer or
	 * integer.
	 *
	 * If unique identification of completions is desired this should be
	 * unique as well.
	 */
 void *userdata;

 union {

  /** OP_TX */
  struct {
   uint32_t buf_len;
   const uint8_t *buf;
  } tx;

  /** OP_RX */
  struct {
   uint32_t buf_len;
   uint8_t *buf;
  } rx;

  /** OP_TINY_TX */
  struct {
   uint8_t buf_len;
   uint8_t buf[7];
  } tiny_tx;

  /** OP_CALLBACK */
  struct {
   rtio_callback_t callback;
   void *arg0;
  } callback;

  /** OP_TXRX */
  struct {
   uint32_t buf_len;
   const uint8_t *tx_buf;
   uint8_t *rx_buf;
  } txrx;

  /** OP_I2C_CONFIGURE */
  uint32_t i2c_config;

  /** OP_I3C_CONFIGURE */
  struct {
   /* enum i3c_config_type type; */
   int type;
   void *config;
  } i3c_config;

  /** OP_I3C_CCC */
  /* struct i3c_ccc_payload *ccc_payload; */
  void *ccc_payload;
 };
};

