/**
 * @brief Prepare a nop (no op) submission
 */
static inline void rtio_sqe_prep_nop(struct rtio_sqe *sqe,
    const struct rtio_iodev *iodev,
    void *userdata)
{
 memset(sqe, 0, sizeof(struct rtio_sqe));
 sqe->op = 0;
 sqe->iodev = iodev;
 sqe->userdata = userdata;
}

