{
 memset(sqe, 0, sizeof(struct rtio_sqe));
 sqe->op = (0 +1);
 sqe->prio = prio;
 sqe->iodev = iodev;
 sqe->rx.buf_len = len;
 sqe->rx.buf = buf;
 sqe->userdata = userdata;
}

