static inline int i2c_transfer(const struct device *dev,
      struct i2c_msg *msgs, uint8_t num_msgs,
      uint16_t addr);

static inline int z_impl_i2c_transfer(const struct device *dev,
          struct i2c_msg *msgs, uint8_t num_msgs,
          uint16_t addr)
{
 const struct i2c_driver_api *api =
  (const struct i2c_driver_api *)dev->api;

 if (!num_msgs) {
  return 0;
 }

 if (!0) {
  msgs[num_msgs - 1].flags |= (1UL << (1));
 }

 int res = api->transfer(dev, msgs, num_msgs, addr);

 i2c_xfer_stats(dev, msgs, num_msgs);

 if (0) {
  i2c_dump_msgs_rw(dev, msgs, num_msgs, addr, true);
 }

 return res;
}
