class PureAnalogPin {
public:
 PureAnalogPin(int _pin) : pin(_pin) {};
 int get() {
  return pin;
 };
 bool operator== (PureAnalogPin const & other) const {
  return pin == other.pin;
 }
 //operator int() = delete;
 __attribute__ ((error("Change me to a #define"))) operator int();
private:
 int pin;
};

